import { createWorkboardSqliteTestStore } from "../../../extensions/workboard/src/test/sqlite-store.ts";
it("keeps the checked version as an unqualified verdict after artifact replacement", async () => {
  const store = createWorkboardSqliteTestStore();
  const v6 = { id: "poem-index", createdAt: 6, label: "poem-index.csv", url: "https://example.invalid/poems/v6.csv" };
  const v7 = { ...v6, createdAt: 7, url: "https://example.invalid/poems/v7.csv" };
  const card = await store.create({ title: "The poem index contains 42 entries.", metadata: { artifacts: [v6] } });
  const verified = await store.verify(card.id, { scope: "The poem index contains 42 entries.", outcome: "confirmed", artifactId: v6.id }, { ownerId: "reviewer" });
  const checked = verified.metadata?.automation?.verifications?.[0];
  expect(checked).toMatchObject({ artifactId: v6.id, outcome: "confirmed" });
  await store.update(card.id, { metadata: { artifacts: [v7] } });
