  const after = current?.metadata?.automation?.verifications?.[0];
  expect(after).toEqual(checked);
  expect(after).not.toHaveProperty("stale");
  for (const [version, verdict] of [[6,checked],[7,after]]) console.log(JSON.stringify({scenario:"poem-index.csv", evidenceVersion:version, verdict, warning:false}));
