<summary>proof script source (proof-live.ts)</summary>

```typescript
import assert from "node:assert/strict";
import { mkdtemp, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { SqliteWorkerBroker } from "./src/infra/sqlite-worker-broker.js";
import type { SqliteWorkerStateContext } from "./src/infra/sqlite-worker-state-context.js";
import type { FixtureOperations } from "./src/infra/sqlite-worker-store.test-support.js";

const temp = await mkdtemp(path.join(os.tmpdir(), "openclaw-sqlite-broker-proof-"));
const broker = new SqliteWorkerBroker();
const cyclicSelection: Record<string, unknown> = {};
cyclicSelection.self = cyclicSelection;
const stateContext = {
  environment: { ...process.env, OPENCLAW_STATE_DIR: temp },
  databaseEngineSelection: cyclicSelection,
} as unknown as SqliteWorkerStateContext;
const moduleUrl = new URL("./src/infra/sqlite-worker-store.test-support.ts", import.meta.url);
let rejectedOpens = 0;
try {
  for (let index = 0; index < 64; index++) {
    try {
      await broker.open<FixtureOperations>(
        { moduleUrl, databasePath: path.join(temp, "failed.sqlite"), input: undefined },
        stateContext,
      );
    } catch {
      rejectedOpens++;
    }
  }
  const store = await broker.open<FixtureOperations>({
    moduleUrl,
    databasePath: path.join(temp, "valid.sqlite"),
    input: undefined,
  });
  assert(store, "valid SQLite worker did not open");
  const result = await store.execute({ type: "append", input: { value: "recovered" } });
  assert.equal(result.writes, 1);
  assert.equal(rejectedOpens, 64);
  console.log(JSON.stringify({ rejectedOpens, recoveredWriteCount: result.writes }));
} finally {
  await broker.close();
  await rm(temp, { recursive: true, force: true });
}
```
